import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Combate Legacy y Modern","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/legacy-and-modern.md","filePath":"es/guide/combat/legacy-and-modern.md"}'),n={name:"es/guide/combat/legacy-and-modern.md"};function i(r,e,c,s,l,m){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="legacy-and-modern-combat" tabindex="-1">Combate Legacy y Modern <a class="header-anchor" href="#legacy-and-modern-combat" aria-label="Enlace permanente a &quot;Combate Legacy y Modern&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · El nuevo diseño no está establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Ambos modos seleccionan un objetivo y comparten valores de armas, costes y fases de acción.</li><li>Legacy usa cadencia automática; Modern permite iniciar las acciones disponibles.</li><li>Modern es la dirección experimental preferida; Legacy sigue siendo una alternativa de diseño compatible.</li></ul><p>Ambos modos parten de un objetivo seleccionado y comparten los valores base de armas. Modern cambia cuándo iniciás una acción; no concede daño oculto.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Legacy</th><th>Modern</th></tr></thead><tbody><tr><td>Selección de objetivo</td><td>Seleccionar primero</td><td>Seleccionar primero</td></tr><tr><td>Ataque básico</td><td>Cadencia automática</td><td>La entrada inicia una acción disponible</td></tr><tr><td>SA ofensivo</td><td>Encolar el siguiente golpe válido</td><td>Activar una acción disponible</td></tr><tr><td>SA defensivo</td><td>Manual cuando esté disponible</td><td>Manual cuando esté disponible</td></tr><tr><td>Stamina</td><td>Costes base compartidos</td><td>Los mismos; apresurarse añade costes</td></tr><tr><td>Recuperación</td><td>Todas las fases deben terminar</td><td>Todas las fases deben terminar</td></tr><tr><td>Alcance</td><td>Huella del arma/acción</td><td>La misma huella</td></tr><tr><td>Flow</td><td>Sin capa de Flow</td><td>Un ritmo estable puede dar pequeños beneficios</td></tr><tr><td>Control temporal</td><td>Anticipar el siguiente golpe</td><td>Elegir cuándo comprometerse</td></tr><tr><td>Experiencia inicial</td><td>Menos presión de entradas</td><td>Más responsabilidad directa sobre los tiempos</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><ul><li>«Inmediato» significa inicio, no impacto instantáneo ni cancelación de recuperación.</li><li>Legacy sigue como alternativa propuesta de accesibilidad/familiaridad.</li><li>Modern es la dirección experimental preferida, no un reemplazo con estado Aceptado.</li><li>La arquería básica no exige un juego de tiempos. Modern controla la liberación; apuntar quieto puede ayudar. Legacy libera según cadencia.</li><li>Algunas SA a distancia pueden compartir un desafío de tiempos en ambos modos; aquí los arcos no reciben valores nuevos.</li></ul><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Encolá Longsword Thrust en Legacy para el siguiente golpe válido, o activalo en Modern cuando esté disponible. En ambos casos pagás su stamina y completás sus fases.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/numeric-prototype.html">Perfil numérico</a> · <a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/game-design/combat/legacy-and-modern.html">Diseño completo</a></p>',13)])])}const b=a(n,[["render",i]]);export{p as __pageData,b as default};
